const modal=document.querySelector("#bookingModal"),form=document.querySelector("#bookingForm");
const serviceNames={swedish:"Swedish Massage",deep:"Deep Tissue Massage",couples:"Couples Massage",sports:"Sports Massage",villa:"Villa Massage",hotel:"Hotel / In-Room Massage",yacht:"Yacht Massage",mobile:"Mobile Massage"};
function openBooking(service="swedish",duration="60"){if(!modal||!form)return;modal.classList.add("open");document.body.style.overflow="hidden";if(form.service)form.service.value=service;if(form.duration)form.duration.value=duration}
function closeBooking(){if(!modal)return;modal.classList.remove("open");document.body.style.overflow=""}
document.addEventListener("click",e=>{const b=e.target.closest("[data-book]");if(b){e.preventDefault();openBooking(b.dataset.service||"swedish",b.dataset.duration||"60")}if(e.target.matches("[data-close]")||e.target===modal)closeBooking()});
document.addEventListener("keydown",e=>{if(e.key==="Escape")closeBooking()});
document.querySelectorAll(".faq-q").forEach(b=>b.addEventListener("click",()=>b.parentElement.classList.toggle("open")));
document.querySelectorAll(".pay-card").forEach(card=>card.addEventListener("click",()=>{document.querySelectorAll(".pay-card").forEach(x=>x.classList.remove("selected"));card.classList.add("selected");card.querySelector("input").checked=true}));
if(form)form.addEventListener("submit",async e=>{e.preventDefault();const d=new FormData(form);const payload={service:d.get("service"),duration:d.get("duration"),date:d.get("date"),time:d.get("time"),location:d.get("location"),name:d.get("name"),phone:d.get("phone"),email:d.get("email"),payment:d.get("payment"),notes:d.get("notes")||"",website:d.get("website")||"",source:location.href};let err=form.querySelector(".booking-error");if(err)err.remove();const btn=form.querySelector('button[type="submit"]');const old=btn.textContent;btn.disabled=true;btn.textContent="Sending request…";try{const r=await fetch("/api/booking-request",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(payload)});const data=await r.json();if(!r.ok)throw new Error(data.error||"Request failed");const panel=modal.querySelector(".booking-panel");panel.innerHTML=`<div class="success"><div class="success-check">✓</div><p class="eyebrow">REQUEST RECEIVED</p><h2>We've got your St. Barths massage request.</h2><p>A confirmation email has been sent to <strong>${payload.email}</strong>. Your requested time remains pending until therapist availability is confirmed.</p><p><strong>Reference: ${data.reference}</strong></p><div class="success-summary"><div><span>Service</span><strong>${serviceNames[payload.service]||payload.service}</strong></div><div><span>Duration</span><strong>${payload.duration} minutes</strong></div><div><span>Date</span><strong>${payload.date}</strong></div><div><span>Time</span><strong>${payload.time}</strong></div><div><span>Location</span><strong>${payload.location}</strong></div><div><span>Payment</span><strong>${payload.payment==="pay"?"Pay online":"Pay in person"}</strong></div></div>${payload.payment==="pay"?`<div style="margin-top:18px;background:#edf8f6;padding:16px"><strong>Online payment selected.</strong><p style="margin:.5rem 0 0">We will confirm availability and send the secure payment link. No charge has been taken yet.</p></div>`:`<div style="margin-top:18px;background:#edf8f6;padding:16px">No payment was taken. We will contact you shortly to confirm therapist availability and appointment details.</div>`}<button class="btn btn-dark" data-close style="margin-top:18px">Close</button></div>`}catch(ex){const box=document.createElement("div");box.className="booking-error";box.textContent="We couldn't send your request. Please try again or use the Need help button.";form.appendChild(box);btn.disabled=false;btn.textContent=old}});
document.querySelectorAll("[data-gallery]").forEach(el=>el.addEventListener("click",()=>{const lb=document.querySelector("#lightbox"),im=document.querySelector("#lightboxImage");im.src=el.dataset.gallery;lb.classList.add("open");document.body.style.overflow="hidden"}));document.addEventListener("click",e=>{const lb=document.querySelector("#lightbox");if(e.target.matches("[data-lightbox-close]")||e.target===lb){lb?.classList.remove("open");document.body.style.overflow=""}});
(()=>{const d=document.createElement("div");d.className="contact-dock";d.innerHTML='<div class="contact-menu" hidden><span>Need help booking?</span><a href="https://wa.me/12428168286" target="_blank"><b>WhatsApp</b><small>Message our concierge</small></a><a href="sms:+12428168286"><b>iMessage / Text</b><small>+1 (242) 816-8286</small></a></div><button class="contact-trigger">Need help?</button>';document.body.appendChild(d);const m=d.querySelector(".contact-menu"),b=d.querySelector(".contact-trigger");b.onclick=()=>m.hidden=!m.hidden})();